const softDeleteConnection = `-- name: SoftDeleteConnection :execrows
UPDATE connections SET deleted_at = now()
WHERE id = $1 AND deleted_at IS NULL AND NOT temporary
`

func (q *Queries) SoftDeleteConnection(ctx context.Context, id uuid.UUID) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteConnection, id)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

